import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
print(json.dumps(G['Demo pair 1 output']))

import collections, json
def f(g):
    bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0]
    H,W=len(g),len(g[0])
    cand=[]
    for i in range(H):
        for j in range(W):
            col=g[i][j]
            if col==bg: continue
            for h2 in range(1,H-i+1):
                if any(g[i+r][j]!=col for r in range(h2)): break
                for w in range(1,W-j+1):
                    if any(g[i][j+c]!=col for c in range(w)): break
                    cand.append((h2*w,h2,w,i,j,col))
    cand.sort(reverse=True)
    _,h,w,i,j,col=cand[0]
    out=[[bg]*W for _ in range(H)]
    for r in range(i,i+h):
        for c in range(j,j+w):
            out[r][c]=col
    return out
